contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address account, uint256 tokenId, uint256 amount) public payable {
        // caller (this contract) has not been set as an allowed burning address
        uint256 balBefore = c.balanceOf(account, tokenId); if (__ESBMC_reverted()) return;
        bool reverted1;
        c.burn(account, tokenId, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted1 = true;
        } else {
            reverted1 = false;
        }
        // grant ourselves burning rights (we are admin, we deployed c)
        c.setAllowedBurningAddresses(address(this)); if (__ESBMC_reverted()) return;
        uint256 balMid = c.balanceOf(account, tokenId); if (__ESBMC_reverted()) return;
        bool reverted2;
        // balance is zero and cannot be increased without minting via the Neuron flow,
        // so burning more than the balance must revert
        c.burn(account, tokenId, amount); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            reverted2 = true;
        } else {
            reverted2 = false;
        }
        assert(
            reverted1 == true &&
            reverted2 == (amount > balMid) &&
            c.balanceOf(account, tokenId) == balBefore &&
            (reverted1 || c.balanceOf(account, tokenId) + amount <= type(uint256).max)
        );
    }
    receive() external payable {}
}

